using System.Text; using Microsoft.AspNetCore.Authorization; using Microsoft.AspNetCore.Mvc; using OCRS.Models.Enums; using OCRS.Services;
namespace OCRS.Areas.Admin.Controllers;
[Area("Admin"),Authorize(Roles="Admin")] public class ReportsController(IReportService reports):Controller { public async Task<IActionResult> Index(DateTime? from,DateTime? to,int? courseId,int? classId,EnrollmentStatus? status)=>View(await reports.GetAsync(from,to,courseId,classId,status)); public async Task<FileResult> Csv(DateTime? from,DateTime? to,int? courseId,int? classId,EnrollmentStatus? status){var rows=await reports.GetAsync(from,to,courseId,classId,status);var b=new StringBuilder("Mã học viên,Họ tên,Email,Khóa học,Lớp,Trạng thái,Ngày đăng ký\r\n");foreach(var r in rows)b.AppendLine(string.Join(',',new[]{r.StudentCode,r.StudentName,r.Email,r.Course,r.Class,r.Status,r.RegisteredAt.ToString("dd/MM/yyyy HH:mm")}.Select(Escape)));return File(Encoding.UTF8.GetPreamble().Concat(Encoding.UTF8.GetBytes(b.ToString())).ToArray(),"text/csv",$"bao-cao-{DateTime.Now:yyyyMMdd}.csv");} private static string Escape(string s)=>$"\"{s.Replace("\"","\"\"")}\""; }
